import { writeOutput } from "./codegen";

const DOCS_URL = "https://developer.paypal.com/api/rest/authentication/";

export async function generate(): Promise<void> {
  writeOutput(
    "paypal",
    [
      "// Auto-generated from PayPal REST API docs.",
      `// Source: ${DOCS_URL}`,
      "// Regenerate: cd turbo && pnpm -F @vm0/firewalls-generator generate:paypal",
      "//",
      "// DO NOT EDIT THIS FILE MANUALLY.",
      "",
      'import type { FirewallConfig } from "../firewall-types";',
      "",
      "export const paypalFirewall = {",
      '  name: "paypal",',
      '  description: "PayPal REST API",',
      "  placeholders: {",
      '    PAYPAL_TOKEN: "CoffeeSafeLocalCoffeeSafeLocalCoffeeSafeLocal",',
      "  },",
      "  apis: [",
      "    {",
      '      base: "https://api-m.paypal.com",',
      '      auth: { headers: { Authorization: "Bearer ${{ secrets.PAYPAL_TOKEN }}" } },',
      "      permissions: [],",
      "    },",
      "  ],",
      "} as const satisfies FirewallConfig;",
      "",
    ].join("\n"),
  );
}
